import { Box, Stack, Tooltip, Typography } from '@mui/material'
import type { AgentConversation } from '../../../../data/data_types'
import type { ActionRunHistoryEntry, CommitReference } from '../../../../data/electron_action_bridge'
import { actionCardAgentTokenUsage } from '../../../../services/agents/agent_usage'
import { AgentUsageDisplay } from '../../../agents/agent_usage_display'

const NUMBER_FORMAT = new Intl.NumberFormat('en-US')

interface ActionUsageSummaryProps {
    actionId: string
    cardInternalId: string
    conversations: AgentConversation[]
    history: ActionRunHistoryEntry[]
}

interface LineUsage {
    commits: CommitReference[]
    deletions: number
    filesChanged: number
    insertions: number
}

function lineUsage(history: ActionRunHistoryEntry[]): LineUsage {
    const commits = history.flatMap((entry) => entry.commits ?? [])

    return commits.reduce((totals, commit) => ({
        commits: totals.commits,
        deletions: totals.deletions + commit.deletions,
        filesChanged: totals.filesChanged + commit.filesChanged,
        insertions: totals.insertions + commit.insertions,
    }), { commits, deletions: 0, filesChanged: 0, insertions: 0 })
}

function commitLine(commit: CommitReference) {
    return `${commit.commit.slice(0, 7)}: +${NUMBER_FORMAT.format(commit.insertions)} / -${NUMBER_FORMAT.format(commit.deletions)}`
}

/** Compact token and changed-line totals for one agent action on one card. */
export function ActionUsageSummary(props: ActionUsageSummaryProps) {
    const { actionId, cardInternalId, conversations, history } = props
    const usage = actionCardAgentTokenUsage(conversations, actionId, cardInternalId)
    const lines = lineUsage(history)
    const totalLines = lines.insertions + lines.deletions
    const lineTooltip = (
        <Stack spacing={0.5}>
            <Typography color="inherit" variant="caption">
                files changed: {NUMBER_FORMAT.format(lines.filesChanged)}, insertions: {NUMBER_FORMAT.format(lines.insertions)},
                {' '}deletions: {NUMBER_FORMAT.format(lines.deletions)}
            </Typography>
            {lines.commits.map((commit, index) => (
                <Typography color="inherit" key={`${commit.repositoryRoot}\u0000${commit.commit}\u0000${index}`} variant="caption">
                    {commitLine(commit)}
                </Typography>
            ))}
        </Stack>
    )

    return (
        <Box sx={{ alignItems: 'center', display: 'flex', flexWrap: 'wrap', gap: 1 }}>
            <AgentUsageDisplay usage={usage} />
            {lines.commits.length > 0 ? (
                <Tooltip describeChild title={lineTooltip}>
                    <Typography component="span" sx={{ color: 'text.secondary', cursor: 'help' }} tabIndex={0} variant="caption">
                        lines: {NUMBER_FORMAT.format(totalLines)}
                    </Typography>
                </Tooltip>
            ) : null}
        </Box>
    )
}

import { useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import { ActionUsageSummary } from './action_usage_summary'

interface ActionUsageSummaryOwnerProps {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
}

/** Subscribes usage summary to conversation and history data only. */
export function ActionUsageSummaryOwner(props: ActionUsageSummaryOwnerProps) {
    const { action, context, conversationStore, historyStore } = props
    useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const historySnapshot = useSyncExternalStore(historyStore.subscribe, historyStore.getSnapshot, historyStore.getSnapshot)

    useEffect(() => {
        void historyStore.load()
    }, [historyStore])

    if (context.kind !== 'card' || !context.file || !context.cardInternalId || action.type !== 'agent') return null

    return (
        <ActionUsageSummary
            actionId={action.id}
            cardInternalId={context.cardInternalId}
            conversations={conversationStore.conversationOptions(null)}
            history={historySnapshot.entries}
        />
    )
}

import { Box, Stack, Typography } from '@mui/material'
import type { ActionRunLogEntry } from '../../../../data/action_run_types'
import { actionStatusLabel } from '../../shared/action_status'

interface ActionRunStatusProps {
    color: string
    logs: ActionRunLogEntry[]
    status: string
}

/** Presentation-only current run status and log summary. */
export function ActionRunStatus(props: ActionRunStatusProps) {
    const { color, logs, status } = props

    return (
        <Box role="status">
            <Typography color={color} variant="body2">
                {actionStatusLabel(status as ActionRunLogEntry['status'])}
            </Typography>
            {logs.length > 0 ? (
                <Stack spacing={0.5} sx={{ mt: 1 }}>
                    {logs.map((log, index) => (
                        <Typography key={`${log.actionName}-${log.phase}-${index}`} color="text.secondary" variant="caption">
                            {log.phase}: {log.message}{log.stdout || log.stderr ? ` â€” ${log.stdout}${log.stderr}` : ''}
                            {log.thinkingLevel ? ` (thinking: ${log.thinkingLevel})` : ''}
                            {log.accessLevel ? ` (access: ${log.accessLevel})` : ''}
                            {log.approvalPolicy ? ` (approval: ${log.approvalPolicy})` : ''}
                        </Typography>
                    ))}
                </Stack>
            ) : null}
        </Box>
    )
}

import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import { useActionRunSelector } from '../../../hooks/use_action_runs'
import { statusColor } from '../popup/action_popup_defaults'
import type { ActionRunResultStore } from './action_run_result_store'
import { ActionRunStatus } from './action_run_status'

interface ActionRunStatusOwnerProps {
    actionId: string
    context: ActionContext
    resultStore: ActionRunResultStore
}

/** Subscribes command status only to status/log values it renders. */
export function ActionRunStatusOwner({ actionId, context, resultStore }: ActionRunStatusOwnerProps) {
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? null)
    const runLogs = useActionRunSelector(actionId, context, (run) => run?.logs ?? null)
    const local = useSyncExternalStore(resultStore.subscribe, resultStore.getSnapshot, resultStore.getSnapshot)
    const status = runStatus ?? local.status
    const logs = runLogs ?? local.result?.logs ?? []
    if (status === 'idle') return null

    return <ActionRunStatus color={statusColor(status)} logs={logs} status={status} />
}

