const ESCAPE_CHARACTER = String.fromCharCode(27);
const ANSI_ESCAPE_PATTERN = new RegExp(`${ESCAPE_CHARACTER}\\[[0-?]*[ -/]*[@-~]`, 'gu');
const HANDOFF_EVENT_TYPES = new Set([
    'collabAgentToolCall',
    'commandExecution',
    'dynamicToolCall',
    'fileChange',
    'mcpToolCall',
    'plan',
    'webSearch',
]);

function cleanContent(value) {
    return value.replace(ANSI_ESCAPE_PATTERN, '').replace(/\r/g, '').trim();
}

function messageLabel(message) {
    if (message.role === 'user') return 'User';

    return `Assistant${message.agent ? ` (${message.agent})` : ''}`;
}

function normalizeMessage(message) {
    const content = cleanContent(message.content);
    if (content.length === 0) return null;

    return { content, label: messageLabel(message), sequence: message.sequence, timestamp: message.timestamp };
}

function normalizeEvent(event) {
    if (event.type === 'error') {
        const content = cleanContent(event.content);

        return content.length > 0
            ? { content, label: 'Failure', sequence: event.sequence, timestamp: event.timestamp }
            : null;
    }
    if (event.type.startsWith('tool.')) {
        const content = cleanContent(event.content);
        if (content.length === 0) return null;
        const toolType = event.type.slice('tool.'.length);

        return {
            content,
            label: toolType === 'result' ? 'Tool result' : `Tool (${toolType})`,
            sequence: event.sequence,
            timestamp: event.timestamp,
        };
    }
    if (!HANDOFF_EVENT_TYPES.has(event.type)) return null;
    const content = [event.command, event.content, event.output]
        .filter((value, index, values) => typeof value === 'string' && value.length > 0 && values.indexOf(value) === index)
        .map(cleanContent)
        .filter((value) => value.length > 0)
        .join('\n\n');
    if (content.length === 0) return null;

    return {
        content,
        label: event.label ?? event.type,
        sequence: event.sequence,
        timestamp: event.timestamp,
    };
}

function entriesAfterCursor(conversation, afterMessageId) {
    if (!afterMessageId) return conversation.entries;
    const cursorIndex = conversation.entries.findIndex((entry) => entry.kind === 'message' && entry.id === afterMessageId);

    return cursorIndex < 0 ? conversation.entries : conversation.entries.slice(cursorIndex + 1);
}

function removeConsecutiveDuplicates(items) {
    return items.filter((item, index) => index === 0 || item.label !== items[index - 1].label || item.content !== items[index - 1].content);
}

function normalizeConversationContext(conversation, afterMessageId = null) {
    const items = removeConsecutiveDuplicates(entriesAfterCursor(conversation, afterMessageId)
        .map((entry) => entry.kind === 'message' ? normalizeMessage(entry) : normalizeEvent(entry))
        .filter((entry) => entry));
    if (items.length === 0) return '';

    return ['MDÂ² conversation context', ...items.flatMap(({ content, label }) => [`[${label}]`, content])].join('\n\n');
}

module.exports = { normalizeConversationContext };

const { createMessageEntry } = require('./agent_conversation');

function nextConversationSequence(conversation) {
    const highestSequence = conversation.entries.reduce((highest, entry) => (
        Number.isSafeInteger(entry.sequence) ? Math.max(highest, entry.sequence) : highest
    ), 0);

    return Math.max(highestSequence, conversation.entries.length) + 1;
}

function nextRunSequence(run) {
    const sequence = run.nextSequence;
    run.nextSequence += 1;

    return sequence;
}

function createProviderEventEntryIndexes(entries) {
    const providerEventEntryIndexes = new Map();
    for (const [index, entry] of entries.entries()) {
        if (entry.kind === 'event' && typeof entry.providerItemId === 'string' && !providerEventEntryIndexes.has(entry.providerItemId)) {
            providerEventEntryIndexes.set(entry.providerItemId, index);
        }
    }

    return providerEventEntryIndexes;
}

function appendDiagnosticContent(eventEntry, content) {
    return { ...eventEntry, content: `${eventEntry.content}\n${content}` };
}

function lastMessageEntry(conversation) {
    return conversation.entries.findLast(({ kind }) => kind === 'message');
}

function assistantMessageId(run) {
    return run.streaming ? `${run.id}-turn-${run.turnIndex}-assistant` : `${run.id}-assistant`;
}

function startAssistantItem(run, itemId, timestamp) {
    if (run.assistantItems.has(itemId)) throw new Error(`Duplicate assistant item ${itemId}`);
    run.assistantItemIndex += 1;
    const item = {
        messageId: `${run.id}-turn-${run.turnIndex}-assistant-${run.assistantItemIndex}`,
        sequence: nextRunSequence(run),
    };
    run.assistantItems.set(itemId, item);
    run.currentAssistantMessageId = item.messageId;
    run.conversation.entries.push(createMessageEntry(
        item.messageId,
        'assistant',
        '',
        timestamp,
        run.agent,
        item.sequence,
    ));

    return item;
